export async function run(inputs, ctx) {
    const token = process.env.GH_TOKEN;
    if (!token) {
        throw new Error("GH_TOKEN secret is not configured");
    }
    const url = `https://api.github.com/repos/${inputs.repository}/issues/${inputs.issueNumber}/comments`;
    ctx.log("Commenting on", inputs.repository, "#" + inputs.issueNumber);
    const response = await fetch(url, {
        method: "POST",
        headers: {
            Authorization: `Bearer ${token}`,
            Accept: "application/vnd.github+json",
            "Content-Type": "application/json",
        },
        body: JSON.stringify({ body: inputs.body }),
    });
    if (!response.ok) {
        throw new Error(`GitHub returned ${response.status}: ${await response.text()}`);
    }
    const comment = await response.json();
    return { commentUrl: comment.html_url };
}
